import sys

largeVal = int(1e6)

def compute(index, positive, negative, carry):
    trueCarry = carry - 50
    if index == 17:
        if positive + negative + trueCarry == 0:
            return 0
        return largeVal
    if cacheDP[index][positive][negative][carry] != -1:
        return cacheDP[index][positive][negative][carry]
    minResult = largeVal
    for p in range(0, min(16, positive) + 1):
        for n in range(0, min(16, negative) + 1):
            sum_val = positive - negative + trueCarry
            digit = (sum_val % 10 + 10) % 10
            nextCarry = (sum_val // 10) if sum_val > 0 else ((sum_val - 9) // 10)
            if digit != int(reversedNumber[index]):
                continue
            result = compute(index + 1, positive - p, negative - n, nextCarry + 50) + (p + n) * (index + 1)
            if result < minResult:
                minResult = result
    cacheDP[index][positive][negative][carry] = minResult
    return minResult

def main():
    inputVal = int(sys.stdin.read().strip())
    maxSize = 50
    global cacheDP, reversedNumber
    cacheDP = [[[[-1 for _ in range(100)] for _ in range(maxSize)] for _ in range(maxSize)] for _ in range(20)]
    reversedNumber = str(inputVal)
    while len(reversedNumber) < 17:
        reversedNumber = "0" + reversedNumber
    reversedNumber = reversedNumber[::-1]
    minRes = largeVal
    for p in range(maxSize):
        for n in range(maxSize):
            res = compute(0, p, n, 50)
            if res < minRes:
                minRes = res
    print(minRes)

if __name__ == "__main__":
    main()

